const opText=s=>esc(s);
function opTable(heads,rows,paginate=true){const total=rows.length;if(paginate&&total>12)rows=rows.slice((ops.page-1)*12,ops.page*12);return `<div class="table-scroll"><table class="ops-table"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${heads.length}" class="empty">Nessun dato corrisponde ai filtri selezionati.</td></tr>`}</tbody></table></div>${paginate&&total>12?`<div class="table-footer"><span>${(ops.page-1)*12+1}–${Math.min(ops.page*12,total)} di ${total}</span><div class="pagers"><button data-ops-page="${ops.page-1}" ${ops.page===1?'disabled':''} aria-label="Pagina precedente">‹</button><button class="active">${ops.page}</button><button data-ops-page="${ops.page+1}" ${ops.page*12>=total?'disabled':''} aria-label="Pagina successiva">›</button></div></div>`:''}`;}
function opPanel(title,rows,heads){return `<section class="panel">${panelHead(title,'list')}${opTable(heads,rows)}</section>`;}
function opTabsMarkup(view){return `<div class="ops-tabs" role="group" aria-label="Sezioni ${titles[view]}">${opTabs[view].map(([id,label])=>`<button data-ops-tab="${id}" class="${ops.tab[view]===id?'active':''}" aria-pressed="${ops.tab[view]===id}">${label}</button>`).join('')}</div>`;}
function opToolbar(extra=''){return `<div class="ops-toolbar"><input type="search" id="ops-query" aria-label="Cerca nella scheda" placeholder="Cerca nei dati della scheda…" value="${esc(ops.query)}">${extra}<button class="btn" data-ops-export="csv">${icon('download')}CSV</button>${state.view==='personnel'?'<button class="btn" data-ops-export="xlsx">XLSX</button>':''}<button class="btn" data-ops-export="pdf">${icon('file')}Stampa / PDF</button></div>`;}
function opSelect(key,label,values){return `<select data-ops-filter="${key}" aria-label="${label}"><option value="all">${label}</option>${values.map(v=>`<option value="${v}" ${ops[key]===v?'selected':''}>${v}</option>`).join('')}</select>`;}
function opSearch(arr){return scoped(arr).filter(r=>Object.values(r).join(' ').toLowerCase().includes(ops.query.toLowerCase())||facilities[r.facility].name.toLowerCase().includes(ops.query.toLowerCase()));}
function peopleRows(){return opSearch(personnel).filter(p=>(ops.role==='all'||p.role===ops.role)&&(ops.level==='all'||p.level===ops.level)&&(ops.presence==='all'||p.presence===ops.presence)&&(ops.training==='all'||p.training===ops.training));}
function opKpis(items){return `<div class="ops-kpis">${items.map(([label,value,foot,ic])=>metric(label,value,foot,ic||'chart')).join('')}</div>`;}
function calendar(){return `<section class="panel">${panelHead('Scadenze · settembre 2026','clock')}<div class="ops-calendar">${['L','M','M','G','V','S','D'].map(x=>`<span class="day-label">${x}</span>`).join('')}<span></span>${Array.from({length:30},(_,i)=>`<span class="${i+1===16?'today':[18,20,30].includes(i+1)?'due':''}">${i+1}</span>`).join('')}</div>${[['18','Verifica documentale','RSPP'],['20','Report mensile','Responsabile commessa'],['30','Dossier prodotti','Ufficio acquisti']].map(([d,t,o])=>`<div class="ops-event"><b>${d}</b><p>${t}<br><small>${o}</small></p></div>`).join('')}</section>`;}
function complianceView(){const all=scoped(obligations),rows=opSearch(obligations).filter(o=>ops.complianceStatus==='all'||o.status===ops.complianceStatus);let body='';if(ops.tab.compliance==='obligations')body=opPanel('Registro adempimenti contrattuali',rows.map(o=>[o.title,o.reference,o.owner,o.date,badge(o.status),`<button class="link" data-obligation="${o.id}">Evidenza ${icon('chevron')}</button>`]),['Adempimento','Riferimento','Responsabile','Scadenza','Stato','Evidenza']);if(ops.tab.compliance==='deadlines')body=`<div class="ops-split">${opPanel('Prossime scadenze',rows.filter(o=>o.status!=='Completato').slice(0,20).map(o=>[o.date,o.title,short(facilities[o.facility]),o.owner,badge(o.status)]),['Scadenza','Adempimento','Impianto','Responsabile','Stato'])}${calendar()}</div>`;if(ops.tab.compliance==='penalties')body=opPanel('Contestazioni e penali',opSearch(ncs).map(n=>[n.id,short(facilities[n.facility]),esc(n.title),'€ 0,00','Da quantificare','In istruttoria',`<button class="link" data-nc="${n.id}">Dettaglio</button>`]),['Evento','Impianto','Motivazione','Importo applicato','Importo potenziale','Stato istruttoria','']);if(ops.tab.compliance==='evidence')body=opPanel('Repository evidenze',rows.map(o=>[o.evidence,short(facilities[o.facility]),o.title,o.date,`<button class="link" data-obligation="${o.id}">Scheda documentale</button>`]),['Documento','Impianto','Obbligo collegato','Aggiornamento','']);return opKpis([['Adempimenti completati',all.filter(o=>o.status==='Completato').length,'Su '+all.length+' obblighi','shield'],['In scadenza',all.filter(o=>o.status==='In scadenza').length,'Scadenze del mese','clock'],['Documenti da aggiornare',all.filter(o=>o.status==='Da aggiornare').length,'Verifiche documentali','file'],['Contestazioni',scoped(ncs).length,'Importi da valutare','alert']])+opTabsMarkup('compliance')+opToolbar(opSelect('complianceStatus','Tutti gli stati',['Completato','In scadenza','Programmata','Da aggiornare']))+body;}
function personnelView(){const all=scoped(personnel),rows=peopleRows();const body=ops.tab.personnel==='people'?opPanel('Elenco operatori',rows.map(p=>[p.id,`<strong>${p.name}</strong>`,short(facilities[p.facility]),p.role,p.level,p.shift,p.contract+' h',p.worked+' h',badge(p.presence),badge(p.training),`<button class="row-btn" data-person="${p.id}">${icon('chevron')}</button>`]),['ID','Operatore','Impianto','Ruolo','Livello CCNL','Turno','Ore contrattuali / sett.','Ore svolte / sett.','Presenza','Formazione','']):opPanel('Formazione e aggiornamenti',rows.map(p=>[p.name,short(facilities[p.facility]),'Sicurezza · CAM · uso attrezzature','16 h','4 h','Superato · 90/100',p.due,badge(p.training),`<button class="link" data-person="${p.id}">Attestati e dettaglio</button>`]),['Operatore','Impianto','Corsi','Ore formazione','Affiancamento','Test / esito','Scadenza','Stato','']);return opKpis([['Operatori attivi',all.length,'Anagrafica demo','users'],['Presenti oggi',all.filter(p=>p.presence==='Presente').length,'Turni della giornata','check'],['Assenti / sostituti',all.filter(p=>p.presence==='Assente').length+' / '+all.filter(p=>p.presence==='Sostituto').length,'Copertura assenze','users'],['Ore contr. / svolte',all.reduce((s,p)=>s+p.contract,0)+' / '+all.reduce((s,p)=>s+p.worked,0),'Settimana dimostrativa','clock'],['Formazione conforme',Math.round(all.filter(p=>p.training==='Conforme').length/all.length*100)+'%','Stato degli aggiornamenti','shield']])+opTabsMarkup('personnel')+opToolbar(opSelect('role','Tutti i ruoli',['Addetto pulizie','Caposquadra'])+opSelect('level','Tutti i livelli',['2','3','4'])+opSelect('presence','Tutte le presenze',['Presente','Assente','Sostituto'])+opSelect('training','Tutta la formazione',['Conforme','In scadenza']))+body+`<p class="demo-small">Nominativi, formazione, inquadramento e ore sono dati dimostrativi. Le esportazioni rispettano i filtri attivi.</p>`;}
function qualityPlanView(){const c=scoped(controls),ns=scoped(ncs),tab=ops.tab.qualityplan;let body='';if(tab==='controls')body=opPanel('Controlli di processo e risultato',opSearch(controls).map(c=>[c.id,c.type,short(facilities[c.facility]),c.area,badge(c.outcome),c.score+' / 100',c.auditor,`<button class="link" data-control="${c.id}">Dettaglio</button>`]),['ID','Tipo','Impianto','Area','Esito','LQA / KPI','Auditor','Evidenze']);if(tab==='nc')body=opPanel('Segnalazioni e non conformità',opSearch(ncs).map(n=>[n.id,short(facilities[n.facility]),esc(n.title),badge(n.priority),n.owner,n.sla,badge(n.status),`<button class="link" data-nc="${n.id}">Timeline</button>`]),['Ticket','Impianto','Segnalazione','Criticità','Assegnatario','Scadenza SLA','Stato','']);if(tab==='corrective')body=opPanel('Azioni correttive e verifica efficacia',opSearch(ncs).map(n=>[n.id,esc(n.title),'Verifica in sito','Ripasso e controllo di risultato',n.owner,n.status==='Risolta'?'Verificata nella demo':'Da verificare',`<button class="link" data-nc="${n.id}">Evidenze e storico</button>`]),['Evento','Anomalia','Analisi causa','Intervento','Responsabile','Efficacia','']);if(tab==='csat')body=`<div class="report-grid"><section class="panel">${panelHead('Customer Satisfaction','chart')}<div class="big-chart"><div class="mini-label">Valutazione media / 5 · campione dimostrativo</div><div class="bars">${[4.2,4.3,4.5,4.6,4.7,4.7].map((v,i)=>`<div class="bar" style="height:${v*32}px" title="${['Apr','Mag','Giu','Lug','Ago','Set'][i]}: ${v}/5"><b>${v}</b><span>${['Apr','Mag','Giu','Lug','Ago','Set'][i]}</span></div>`).join('')}</div></div></section>${opPanel('Aree di attenzione',[['Servizi igienici','4,3 / 5','Verifica frequenza ripassi'],['Spogliatoi','4,6 / 5','Controlli durante apertura'],['Aree comuni','4,8 / 5','Mantenimento standard']],['Area','CSAT demo','Indicazione'])}</div>`;if(tab==='audit')body=opPanel('Audit trail · storico delle variazioni',opSearch(audits).map(a=>[a.id,a.origin,a.at,a.author,a.event,esc(a.old),esc(a.next)]),['Record','Origine','Timestamp','Autore / sistema','Evento','Valore precedente','Valore nuovo']);return opKpis([['Controlli eseguiti',c.length,'Processo e risultato','shield'],['Conformità',Math.round(c.filter(x=>x.outcome==='Conforme').length/c.length*100)+'%','Esiti delle verifiche','check'],['NC aperte',ns.filter(n=>n.status!=='Risolta').length,'Segnalazioni in gestione','alert'],['Entro SLA','92%','Scenario dimostrativo','clock'],['Presa in carico / chiusura','7 / 42 min','Tempi medi demo','clock'],['CSAT','4,7 / 5','Valutazione demo','chart']])+`<div class="toolbar"><button class="btn primary" data-action="new-nc">${icon('plus')}Apri segnalazione</button></div>`+opTabsMarkup('qualityplan')+opToolbar()+body+`<section class="panel ops-section">${panelHead('Ciclo di gestione della non conformità','shield')}<div class="ops-workflow">${['Apertura','Presa in carico','Intervento correttivo','Verifica efficacia','Chiusura e storico'].map((s,i)=>`<span><b>${i+1}</b>${s}</span>`).join('')}</div></section>`;}
function sustainabilityView(){const tab=ops.tab.sustainability;let body='';if(tab==='products')body=opPanel('Prodotti e ausiliari',opSearch(products).map(p=>[p.name,p.maker,p.use,short(facilities[p.facility]),p.quantity+' '+p.unit,badge(p.cam),p.label,`<button class="link" data-product="${p.id}">SDS / Scheda</button>`]),['Denominazione','Produttore','Funzione','Impianto','Quantità mese','CAM','Ecolabel / evidenza','']);if(tab==='equipment')body=opPanel('Macchine e dotazioni manuali',opSearch(equipment).map(m=>[m.name,m.type,short(facilities[m.facility]),m.use,m.hours===null?'Non applicabile':m.hours+' h',badge(m.status),`<button class="link" data-equipment="${m.id}">Dettaglio</button>`]),['Modello / dotazione','Tipo','Impianto','Utilizzo','Ore macchina','Stato','']);if(tab==='consumption')body=`<div class="ops-toolbar"><label>Periodo <select id="cam-period"><option value="2026-09" ${ops.period==='2026-09'?'selected':''}>Settembre 2026</option><option value="2026-08" ${ops.period==='2026-08'?'selected':''}>Agosto 2026</option></select></label></div>`+opPanel('Consumi per impianto · '+(ops.period==='2026-09'?'settembre':'agosto')+' 2026',facilities.filter(f=>state.facility===-1||f.id===state.facility).map(f=>[short(f),(ops.period==='2026-09'?12:14)+f.id%5+' L',(35+f.id%10)+' pz',(80+f.id%20)+' pz','100%']),['Impianto','Detergenti','Tessili','Materiali ausiliari','Conformità CAM'])+`<section class="panel ops-section">${panelHead('Indicatori ambientali','leaf')}<div class="panel-body ops-report">Le quantità sono dimostrative. I dati di consumo consentono il confronto per impianto e periodo; gli indicatori di riduzione dell’impatto richiedono una baseline e documenti di comprova validati.</div></section>`;if(tab==='maintenance')body=opPanel('Registro manutenzioni',opSearch(equipment).map(m=>[m.id,m.name,short(facilities[m.facility]),m.last,m.next,badge(m.status),m.status==='In manutenzione'?'Controllo batteria':'Nessuna anomalia',`<button class="link" data-equipment="${m.id}">Registro</button>`]),['Matricola','Dotazione','Impianto','Ultima','Prossima','Stato','Anomalie','']);return opKpis([['Prodotti e ausiliari',scoped(products).length,'Voci in anagrafica','leaf'],['Conformità CAM','100%','Scenario dimostrativo','shield'],['Detergenti',scoped(products).filter(p=>p.unit==='L').reduce((s,p)=>s+p.quantity,0)+' L','Settembre 2026','chart'],['Dotazioni operative',scoped(equipment).filter(e=>e.status==='Operativa').length,'Macchine e attrezzature manuali','wrench'],['In manutenzione',scoped(equipment).filter(e=>e.status==='In manutenzione').length,'Controlli in corso','clock']])+opTabsMarkup('sustainability')+opToolbar()+body;}
function susPortalTabs(){return `<div class="sus-portal-tabs" role="tablist" aria-label="Sostenibilità e dotazioni"><button role="tab" data-sus-tab="cam" class="${ops.tab.sustainability==='cam'?'active':''}">${icon('leaf')}Criteri CAM</button><button role="tab" data-sus-tab="rewards" class="${ops.tab.sustainability==='rewards'?'active':''}">${icon('shield')}Criteri premianti</button>${ops.tab.sustainability==='machines'||ops.tab.sustainability==='machine-detail'?`<button role="tab" data-sus-tab="machines" class="active">${icon('wrench')}Macchine e attrezzature</button>`:''}</div>`;}
function susKpis(items){return `<div class="sus-kpis">${items.map(([label,value,foot,ic,tone,action])=>`<${action?'button':'article'} class="sus-kpi ${action?'clickable':''}" ${action?`data-sus-tab="${action}"`:''}><div class="sus-kpi-label">${icon(ic)}<span>${label}</span></div><strong class="${tone||''}">${value}</strong><small>${foot}</small></${action?'button':'article'}>`).join('')}</div>`;}
function susStatus(value){return `<span class="sus-status ${/Parzial|manutenzione|verifica/i.test(value)?'warning':/Non /i.test(value)?'danger':'ok'}">${esc(value)}</span>`;}
function susCamView(){const categories=['Tutte le categorie','Detergenti','Prodotti ausiliari','Macchine e attrezzature','Formazione','Disinfettanti','Carta tessuto e igiene','Rifiuti'];const rows=camRequirements.filter(r=>ops.susCategory==='all'||r.category===ops.susCategory);return susPortalTabs()+susKpis([['Conformità CAM complessiva','96%','23 su 24 requisiti','shield'],['Prodotti conformi','98%','143 su 146 prodotti','leaf'],['Personale formato','100%','218 su 218 addetti','users'],['Macchine conformi','95%','19 su 20 macchine','wrench','', 'machines'],['Non conformità aperte','2','0 scadute','file']])+`<div class="sus-category-tabs">${categories.map((c,i)=>`<button data-cam-category="${i?'': 'all'}${i?esc(c):''}" class="${(i===0&&ops.susCategory==='all')||ops.susCategory===c?'active':''}">${c}</button>`).join('')}</div><section class="panel sus-panel">${panelHead('Requisiti CAM','list')}<div class="table-scroll"><table class="ops-table sus-table"><thead><tr><th>Categoria</th><th>Requisito CAM</th><th>Target</th><th>Stato</th><th>Ultima verifica</th><th>Evidenze</th><th></th></tr></thead><tbody>${rows.map(r=>{const machines=r.category==='Macchine e attrezzature';return `<tr><td><span class="sus-cell-icon">${icon(r.icon)}</span>${r.category}</td><td>${r.requirement}</td><td>${r.target}</td><td>${susStatus(r.status)}</td><td>${r.date}</td><td><button class="link" ${machines?'data-sus-tab="machines"':`data-sus-evidence="${r.docs}"`}>${r.docs} documenti</button></td><td>${machines?`<button class="row-btn sus-row-link" data-sus-tab="machines" aria-label="Apri Macchinari e Attrezzature">${icon('chevron')}</button>`:icon('chevron')}</td></tr>`;}).join('')}</tbody></table></div></section><div class="sus-bottom-grid"><section class="panel sus-mini-panel">${panelHead('Prodotti consumati (anno 2026)','chart')}<div class="sus-stat-row"><span><b>2.480 L</b>Detergenti ordinari</span><span><b>320 L</b>Detergenti periodici</span><span><b>150 L</b>Disinfettanti</span><span><b>4.892 pz</b>Prodotti ausiliari</span></div></section><button class="panel sus-mini-panel sus-machine-summary" data-sus-tab="machines">${panelHead('Macchine e attrezzature','wrench')}<div class="sus-stat-row"><span><b>20</b>Macchine in uso</span><span><b class="green">95%</b>Conformi ai CAM</span><span><b class="red">3</b>In manutenzione</span></div></button></div>`;}
function susRewardsView(){return susPortalTabs()+susKpis([['Criteri premianti monitorati','7','su 7 previsti','shield'],['Criteri attuati','6','86%','check','green'],['Non conformità','1','0 scadute','alert','red'],['Evidenze documentali','28','documenti caricati','file']])+`<section class="panel sus-panel">${panelHead('Dettaglio criteri premianti','list')}<div class="table-scroll"><table class="ops-table sus-table"><thead><tr><th>#</th><th>Criterio premiante</th><th>Indicatore di monitoraggio</th><th>Target di offerta</th><th>Stato</th><th>Ultima verifica</th><th>Evidenze</th><th></th></tr></thead><tbody>${rewardCriteria.map((r,i)=>`<tr><td>${i+1}</td><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td><td>${susStatus(r[3])}</td><td>${r[4]}</td><td><button class="link" data-sus-evidence="${r[5]}">${r[5]} documenti</button></td><td>${icon('chevron')}</td></tr>`).join('')}</tbody></table></div></section><div class="sus-bottom-grid rewards"><section class="panel sus-chart-panel">${panelHead('Distribuzione per stato di attuazione','clock')}<div class="donut-wrap"><div class="sus-donut"><b>7</b><span>criteri</span></div><div class="sus-legend"><span><i class="green"></i>Raggiunto <b>6 (86%)</b></span><span><i class="amber"></i>Parzialmente attuato <b>1 (14%)</b></span><span><i class="red"></i>Non attuato <b>0 (0%)</b></span></div></div></section><section class="panel sus-chart-panel">${panelHead('Evidenze documentali','wrench')}<div class="sus-bars">${[2,5,6,4,8,4,7,7,12].map((v,i)=>`<span style="--bar:${v}"><i></i><small>${['Gen','Feb','Mar','Apr','Mag','Giu','Lug','Ago','Set'][i]}</small></span>`).join('')}</div></section></div><p class="sus-info">${icon('info')}I criteri premianti sono monitorati in coerenza con quanto offerto in sede di gara. La documentazione è sempre disponibile per la consultazione da parte del DEC.</p>`;}
function machineRows(){return machineModels.filter(m=>(!state.cluster||facilities[m.facility].cluster===state.cluster)&&(state.facility<0||m.facility===state.facility)&&(ops.susType==='all'||m.type===ops.susType)&&(ops.susStatus==='all'||m.status===ops.susStatus)&&Object.values(m).join(' ').toLowerCase().includes(ops.query.toLowerCase()));}
