function trendBars(values){return `<div class="spark-bars">${values.map(v=>`<i style="height:${v}%"></i>`).join('')}</div>`;}
function susMachineDetail(){const m=machineModels.find(x=>x.id===ops.equipmentId)||machineModels[0];const profileLabels=['Tipologia','Pista di lavoro','Resa teorica','Alimentazione','Modalità ECO','Serbatoio acqua','Pressione sonora','Dimensioni (L × P × H)','Peso (con batterie)'];const measures=[['Energia (kWh)',m.energy+' kWh','↓ -12%','≤ 65 kWh','Conforme'],['Acqua (L)',m.water+' L','↓ -8%','≤ 520 L','Conforme'],['Detergente (L)',m.detergent+' L','↑ +4%','≤ 22 L','In verifica'],['Ore utilizzo',m.hours+' h','↑ +9%','n.d.','Monitorato'],['Rumorosità',m.profile[6],'=','< 70 dB(A)','Conforme'],['Emissioni / ECO mode',m.eco+'% utilizzo ECO','↑ +5%','≥ 70%','Conforme']];return `<button class="sus-back" data-equipment-back>${icon('arrow')}Torna a macchine e attrezzature</button><section class="sus-machine-meta">${[['Tipologia',m.type,'wrench'],['Impianto',short(facilities[m.facility]),'building'],['Cluster',m.cluster,'list'],['Stato',susStatus(m.status),'check'],['Conformità CAM',susStatus(m.cam),'shield'],['Ultima manutenzione',m.last,'clock'],['Monitoraggio consumi',susStatus(m.consumption),'chart']].map(r=>`<div>${icon(r[2])}<span>${r[0]}<b>${r[1]}</b></span></div>`).join('')}</section>${susKpis([['Energia totale',m.energy+' kWh','ultimo periodo','chart'],['Acqua totale',m.water+' L','ultimo periodo','leaf'],['Detergente dosato',m.detergent+' L','ultimo periodo','file'],['Ore di utilizzo',m.hours+' h','settembre 2026','clock'],['Modalità ECO',m.eco+'%','% utilizzo','leaf','green'],['Conformità ambientale',m.conformity+'%','Indicatori macchina','shield']])}<div class="sus-section-tabs"><button class="active">Scheda macchina</button><button>Consumi</button><button>Manutenzioni</button><button>Documenti</button><button>Storico</button></div><div class="sus-detail-layout"><div><section class="panel sus-panel">${panelHead('Consumi e prestazioni','list')}<div class="table-scroll"><table class="ops-table sus-table"><thead><tr><th>Indicatore</th><th>Valore periodo</th><th>Trend</th><th>Target</th><th>Stato</th></tr></thead><tbody>${measures.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td class="${r[2].includes('↑')?'red':'green'}">${r[2]}</td><td>${r[3]}</td><td>${susStatus(r[4])}</td></tr>`).join('')}</tbody></table></div></section><section class="panel sus-trends">${panelHead('Andamento ultimi 6 mesi','chart')}<div>${[['Energia (kWh)',m.energy,'↓ -12%',[88,77,69,63,58,49]],['Acqua (L)',m.water,'↓ -8%',[82,80,73,68,62,51]],['Detergente (L)',m.detergent,'↑ +4%',[64,61,55,45,47,44]],['Ore utilizzo',m.hours,'↑ +9%',[52,65,70,58,66,54]]].map((r,i)=>`<article>${icon(['chart','leaf','file','clock'][i])}<span>${r[0]}<b>${r[1]}${i===0?' kWh':i===1?' L':i===2?' L':' h'}</b></span><em class="${r[2].includes('↑')?'red':'green'}">${r[2]}</em>${trendBars(r[3])}</article>`).join('')}</div></section><section class="panel sus-panel">${panelHead('Registro manutenzioni','file')}<div class="table-scroll"><table class="ops-table"><thead><tr><th>Data</th><th>Intervento</th><th>Esito</th><th>Tecnico / Fornitore</th><th>Prossima scadenza</th></tr></thead><tbody>${[['28/08/2026','Verifica sistema dosaggio','Regolare','Fornitore '+m.model.split(' ')[0],'28/02/2027'],['15/06/2026','Controllo batterie e ricarica','Regolare','Tecnico interno','15/12/2026'],['12/03/2026','Manutenzione ordinaria','Regolare','Fornitore '+m.model.split(' ')[0],'12/09/2026'],['10/12/2025','Sostituzione gomme tergi','Completato','Tecnico interno','10/06/2026']].map(r=>`<tr>${r.map((c,i)=>`<td>${i===2?susStatus(c):c}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section></div><aside class="sus-machine-aside"><section class="panel sus-profile">${panelHead('Profilo macchina','building')}<dl><dt>Marca / Modello</dt><dd>${m.model}</dd>${profileLabels.map((l,i)=>`<dt>${l}</dt><dd>${m.profile[i]}</dd>`).join('')}<dt>Scheda tecnica</dt><dd><button class="link" data-sus-evidence="1">${icon('file')}disponibile</button></dd></dl></section><section class="panel sus-chart-panel">${panelHead('Ripartizione consumi','filter')}<div class="donut-wrap"><div class="sus-donut machine"><b>${m.energy+m.water+m.detergent}</b><span>Totale</span></div><div class="sus-legend"><span><i></i>Energia (kWh) <b>${m.energy}</b></span><span><i class="cyan"></i>Acqua (L) <b>${m.water}</b></span><span><i class="light"></i>Detergente (L) <b>${m.detergent}</b></span></div></div></section><section class="panel sus-checklist">${panelHead('Conformità CAM','shield')}${['Plastica riciclata componenti','Sistema riduzione consumi','Riduzione consumi idrici','Dosaggio detergente a bordo','Emissioni acustiche < 70 dB(A)'].map(x=>`<p>${icon('check')}<span>${x}</span><b>Verificata</b></p>`).join('')}</section><section class="panel sus-docs">${panelHead('Documentazione','file')}${['Scheda tecnica','Manuale d’uso','Registro manutenzioni','SDS detergente','Verifica conformità'].map((x,i)=>`<p>${icon('file')}<span>${x}</span><small>${i===2?'4':'1'}</small><button class="link" data-sus-evidence="1">Apri</button></p>`).join('')}</section></aside></div>`;}
function sustainabilityHubView(){if(ops.tab.sustainability==='rewards')return susRewardsView();if(ops.tab.sustainability==='machines')return susMachinesView();if(ops.tab.sustainability==='machine-detail')return susMachineDetail();return susCamView();}
function sustainabilityFilterbar(){const machine=ops.tab.sustainability==='machines';if(ops.tab.sustainability==='machine-detail')return '';return `<div class="filterbar dashboard-filters sus-filters">${icon('filter')}<label>Cluster<select id="cluster-select">${filterOptions([[0,'Tutti i cluster'],...clusters.map(c=>[c.id,`Cluster ${c.id} · ${c.name}`])],state.cluster)}</select></label><label>Impianto<select id="facility-select">${filterOptions([[-1,'Tutti gli impianti'],...facilities.filter(f=>!state.cluster||f.cluster===state.cluster).map(f=>[f.id,f.name])],state.facility)}</select></label><label>Periodo<select id="period-select">${filterOptions([['all',machine?'Tutti i periodi':'Anno 2026'],['today','Oggi · 16 set'],['week','Ultimi 7 giorni'],['month','Settembre 2026']],state.period)}</select></label>${machine?`<label>Tipologia<select id="sus-type-select"><option value="all">Tutte le tipologie</option><option ${ops.susType==='Macchina'?'selected':''}>Macchina</option><option ${ops.susType==='Attrezzatura'?'selected':''}>Attrezzatura</option></select></label><label>Stato<select id="sus-status-select"><option value="all">Tutti gli stati</option><option ${ops.susStatus==='Attiva'?'selected':''}>Attiva</option><option ${ops.susStatus==='In manutenzione'?'selected':''}>In manutenzione</option><option ${ops.susStatus==='In verifica'?'selected':''}>In verifica</option></select></label>`:''}<button class="link" data-action="reset">${icon('refresh')}Reset filtri</button></div>`;}
window.sustainabilityFilterbar=sustainabilityFilterbar;
const baseHeading=heading;
heading=function(){if(state.view!=='sustainability')return baseHeading();const detail=ops.tab.sustainability==='machine-detail',machine=ops.tab.sustainability==='machines',reward=ops.tab.sustainability==='rewards',m=machineModels.find(x=>x.id===ops.equipmentId)||machineModels[0];const title=detail?m.name:machine?'Macchinari e Attrezzature':reward?'Criteri premianti':'Criteri Ambientali Minimi (CAM)';const sub=detail?'Il DEC può monitorare consumi, manutenzioni, conformità ed evidenze della macchina.':machine?'Il DEC può monitorare macchine, attrezzature, stato di manutenzione e consumi ambientali negli impianti.':reward?'Monitoraggio dei criteri premianti previsti dal CAM, con evidenze documentali e stato di attuazione.':'Monitoraggio della conformità ambientale del servizio di pulizia, con evidenze documentali e reportistica.';return `<div class="page-heading"><div><div class="eyebrow">Milanosport · Esecuzione del servizio</div><h1>${title}</h1><p>${sub}</p></div><div class="sus-heading-actions"><button class="btn" data-ops-export="pdf">${icon('download')}Esporta report</button>${!machine&&!detail?`<button class="btn" data-sus-guide>${icon('file')}${reward?'Guida':'Guida CAM'}</button>`:''}</div></div>`;};
window.EXTRA_VIEWS={compliance:complianceView,personnel:personnelView,qualityplan:qualityPlanView,sustainability:sustainabilityHubView};
function personDetail(id){const p=personnel.find(p=>p.id===id);drawer('Scheda individuale · '+p.name,p.id+' · Dati dimostrativi',`<div class="drawer-body">${badge(p.presence)}${details([['Impianto assegnato',esc(facilities[p.facility].name)],['Ruolo',p.role],['Inquadramento','Livello '+p.level+' · esempio CCNL'],['Turno odierno',p.shift],['Ore settimanali',p.contract+' contrattuali / '+p.worked+' svolte'],['DPI e dotazioni','Guanti · calzature di sicurezza · divisa'],['Idoneità e documenti','Stato documentale da collegare al sistema HR']])}<section class="detail-section"><h3>Formazione integrata</h3>${opTable(['Corso','Ore','Esito'],[['Sicurezza generale e specifica','8','Superato'],['CAM e tecniche di pulizia','4','Superato'],['Uso macchine e attrezzature','4','Superato'],['Affiancamento operativo','4','Completato']])}<p>Test demo: 90/100 · Prossimo aggiornamento: ${p.due}.</p><p>Attestati originali non allegati.</p></section><section class="detail-section"><h3>Storico turni · settimana</h3>${opTable(['Giorno','Turno','Presenza'],[['Lun 14',p.shift,'Presente'],['Mar 15',p.shift,'Presente'],['Mer 16',p.shift,p.presence],['Gio 17',p.shift,'Programmato'],['Ven 18',p.shift,'Programmato']])}</section><div class="drawer-actions"><button class="btn primary" data-action="print">${icon('download')}Stampa / PDF</button></div></div>`);}
const baseNcDetail=ncDetail;ncDetail=function(id){baseNcDetail(id);const n=ncs.find(n=>n.id===id);const html=`<section class="detail-section"><h3>Tracciabilità dell’evento</h3>${details([['Origine','DEC / PFE · esempio'],['Presa in carico','16/09/2026 · 08:45'],['Causa','Da verificare in sito'],['Intervento','Ripasso e verifica di risultato'],['Evidenze prima / dopo','Nessuna immagine operativa allegata nella demo'],['Verifica efficacia',n.status==='Risolta'?'Ripristino registrato nella sessione':'In attesa']])}<div class="timeline">${['Apertura della segnalazione','Assegnazione a '+n.owner,'Presa in carico','Intervento correttivo',n.status==='Risolta'?'Verifica e chiusura':'Verifica e chiusura da completare'].map(s=>`<p>${esc(s)}</p>`).join('')}</div></section>`;document.querySelector('#detail .drawer-body').insertAdjacentHTML('beforeend',html);};
function pdiDetail(){drawer('Piano dettagliato degli interventi',selected()?short(selected()):'Tutti gli impianti',`<div class="drawer-body"><div class="ops-detail-note">Il PDI approvato non è presente tra gli allegati ricevuti. Qui è disponibile uno schema dimostrativo; il download del documento contrattuale sarà collegato al file originale.</div>${opTable(['Ambito','Attività','Programmazione'],[['Ordinario','Pulizie giornaliere, periodiche e a fondo','Secondo frequenze approvate per area'],['Ripassi','Mantenimento durante l’apertura','Secondo esigenze e piano'],['Complementari','Rifiuti e spazi confinati','Secondo piano e attivazione'],['Straordinari','Extra-canone','Su richiesta e autorizzazione DEC']])}<div class="drawer-actions"><button class="btn primary" data-action="print">${icon('download')}Stampa / PDF dello schema demo</button></div></div>`);}
function opExportRows(){let heads,rows;if(state.view==='personnel'){heads=['ID','Operatore','Impianto','Ruolo','Livello','Turno','Ore contrattuali settimanali','Ore svolte settimanali','Presenza','Formazione','Ore corsi','Ore affiancamento','Test','Scadenza formazione'];rows=peopleRows().map(p=>[p.id,p.name,facilities[p.facility].name,p.role,p.level,p.shift,p.contract,p.worked,p.presence,p.training,16,4,'90/100',p.due]);}else if(state.view==='compliance'){if(ops.tab.compliance==='penalties'){heads=['ID','Impianto','Contestazione','Importo applicato','Importo potenziale','Stato'];rows=opSearch(ncs).map(n=>[n.id,facilities[n.facility].name,n.title,0,'Da quantificare','In istruttoria']);}else{heads=['Obbligo','Impianto','Riferimento','Responsabile','Scadenza','Stato','Evidenza'];rows=opSearch(obligations).filter(o=>ops.complianceStatus==='all'||o.status===ops.complianceStatus).map(o=>[o.title,facilities[o.facility].name,o.reference,o.owner,o.date,o.status,o.evidence]);}}else if(state.view==='qualityplan'){if(ops.tab.qualityplan==='audit'){heads=['Record','Origine','Timestamp','Autore','Evento','Precedente','Nuovo'];rows=opSearch(audits).map(a=>[a.id,a.origin,a.at,a.author,a.event,a.old,a.next]);}else if(['nc','corrective'].includes(ops.tab.qualityplan)){heads=['ID','Impianto','Segnalazione','Priorità','Responsabile','SLA','Stato'];rows=opSearch(ncs).map(n=>[n.id,facilities[n.facility].name,n.title,n.priority,n.owner,n.sla,n.status]);}else if(ops.tab.qualityplan==='csat'){heads=['Mese','CSAT demo / 5'];rows=['Apr','Mag','Giu','Lug','Ago','Set'].map((m,i)=>[m,[4.2,4.3,4.5,4.6,4.7,4.7][i]]);}else{heads=['ID','Impianto','Tipo','Area','Esito','LQA','Auditor'];rows=opSearch(controls).map(c=>[c.id,facilities[c.facility].name,c.type,c.area,c.outcome,c.score,c.auditor]);}}else{if(['equipment','maintenance'].includes(ops.tab.sustainability)){heads=['ID','Impianto','Dotazione','Tipo','Ore','Stato','Ultima manutenzione','Prossima manutenzione'];rows=opSearch(equipment).map(m=>[m.id,facilities[m.facility].name,m.name,m.type,m.hours??'N/A',m.status,m.last,m.next]);}else if(ops.tab.sustainability==='consumption'){heads=['Impianto','Periodo','Detergenti L','Tessili pz','Ausiliari pz','CAM'];rows=facilities.filter(f=>state.facility===-1||f.id===state.facility).map(f=>[f.name,ops.period,(ops.period==='2026-09'?12:14)+f.id%5,35+f.id%10,80+f.id%20,'100%']);}else{heads=['Prodotto','Produttore','Impianto','Funzione','Quantità','Unità','CAM','Evidenza'];rows=opSearch(products).map(p=>[p.name,p.maker,facilities[p.facility].name,p.use,p.quantity,p.unit,p.cam,p.label]);}}return {heads,rows};}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function opExport(format){let data=opExportRows();if(state.view==='sustainability'){if(ops.tab.sustainability==='machines'||ops.tab.sustainability==='machine-detail')data={heads:['Denominazione','Tipologia','Impianto','Cluster','Stato','Conformità CAM','Ultima manutenzione','Consumi'],rows:machineRows().map(m=>[m.name,m.type,facilities[m.facility].name,m.cluster,m.status,m.cam,m.last,m.consumption])};else if(ops.tab.sustainability==='rewards')data={heads:['Criterio premiante','Indicatore','Target','Stato','Ultima verifica','Evidenze'],rows:rewardCriteria};else data={heads:['Categoria','Requisito CAM','Target','Stato','Ultima verifica','Evidenze'],rows:camRequirements.map(r=>[r.category,r.requirement,r.target,r.status,r.date,r.docs])};}const {heads,rows}=data,name='Milanosport-'+state.view+'-demo';if(format==='pdf'){drawer(titles[state.view],'Esportazione dei dati filtrati · demo',`<div class="drawer-body">${opTable(heads,rows.map(r=>r.map(esc)),false)}<div class="drawer-actions"><button class="btn primary" data-action="print">Stampa / Salva PDF</button></div></div>`);return;}if(format==='xlsx'){downloadBlob(makeXlsx([['MILANOSPORT HUB — DATI DIMOSTRATIVI'],heads,...rows]),name+'.xlsx');}else{downloadBlob(new Blob(['\uFEFF'+[['MILANOSPORT HUB — DATI DIMOSTRATIVI'],heads,...rows].map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),name+'.csv');}toast('Esportazione dei dati filtrati completata');}
function makeXlsx(rows){const xml=s=>String(s).replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]));const col=n=>{let r='';for(n++;n;n=Math.floor((n-1)/26))r=String.fromCharCode(65+(n-1)%26)+r;return r;};const files={'[Content_Types].xml':'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>','_rels/.rels':'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>','xl/workbook.xml':'<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Dati filtrati" sheetId="1" r:id="rId1"/></sheets></workbook>','xl/_rels/workbook.xml.rels':'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>','xl/worksheets/sheet1.xml':'<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><cols><col min="1" max="30" width="24" customWidth="1"/></cols><sheetData>'+rows.map((r,i)=>`<row r="${i+1}">${r.map((v,j)=>`<c r="${col(j)}${i+1}" ${typeof v==='number'?'':'t="inlineStr"'}>${typeof v==='number'?'<v>'+v+'</v>':'<is><t>'+xml(v)+'</t></is>'}</c>`).join('')}</row>`).join('')+'</sheetData></worksheet>'};const enc=new TextEncoder(),parts=[],central=[];let offset=0;const crc=bytes=>{let c=0xffffffff;for(const b of bytes){c^=b;for(let k=0;k<8;k++)c=(c>>>1)^((c&1)?0xedb88320:0);}return (c^0xffffffff)>>>0;};for(const [name,content]of Object.entries(files)){const n=enc.encode(name),b=enc.encode(content),c=crc(b),h=new Uint8Array(30),v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint32(14,c,true);v.setUint32(18,b.length,true);v.setUint32(22,b.length,true);v.setUint16(26,n.length,true);parts.push(h,n,b);const ch=new Uint8Array(46),cv=new DataView(ch.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint32(16,c,true);cv.setUint32(20,b.length,true);cv.setUint32(24,b.length,true);cv.setUint16(28,n.length,true);cv.setUint32(42,offset,true);central.push(ch,n);offset+=h.length+n.length+b.length;}const len=central.reduce((s,p)=>s+p.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,Object.keys(files).length,true);ev.setUint16(10,Object.keys(files).length,true);ev.setUint32(12,len,true);ev.setUint32(16,offset,true);return new Blob([...parts,...central,end],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-home-menu')){document.body.classList.toggle('home-menu-open');b.setAttribute('aria-expanded',document.body.classList.contains('home-menu-open'));}if(b.dataset.scroll){document.body.classList.remove('home-menu-open');document.getElementById(b.dataset.scroll)?.scrollIntoView({behavior:'smooth',block:'start'});}if(b.dataset.hero!==undefined){ops.hero=Number(b.dataset.hero);document.querySelector('.home-hero').innerHTML=heroMarkup();}if(b.dataset.opsPage){ops.page=Number(b.dataset.opsPage);render();}if(b.dataset.opsTab){ops.page=1;ops.tab[state.view]=b.dataset.opsTab;ops.query='';render();}if(b.dataset.opsExport)opExport(b.dataset.opsExport);if(b.hasAttribute('data-pdi'))pdiDetail();if(b.dataset.person)personDetail(b.dataset.person);if(b.dataset.obligation){const o=obligations.find(o=>o.id===b.dataset.obligation);drawer('Evidenza documentale',o.id,`<div class="drawer-body"><h2>${o.title}</h2>${details([['Impianto',esc(facilities[o.facility].name)],['Riferimento',o.reference],['Responsabile',o.owner],['Scadenza',o.date],['Stato',o.status],['Documento atteso',o.evidence]])}<div class="ops-detail-note">Scheda dimostrativa. Il documento originale non è allegato e non viene simulato come certificazione disponibile.</div><div class="drawer-actions"><button class="btn" data-action="print">Stampa scheda / PDF</button></div></div>`);}if(b.dataset.control){const c=controls.find(c=>c.id===b.dataset.control);drawer('Controllo di '+c.type.toLowerCase(),c.id,`<div class="drawer-body">${badge(c.outcome)}${details([['Impianto',facilities[c.facility].name],['Area',c.area],['Esito LQA',c.score+' / 100'],['Auditor',c.auditor],['Data',c.date],['Origine',c.origin],['Evidenze','Nessuna foto allegata nella demo']])}<div class="drawer-actions"><button class="btn primary" data-action="new-nc" data-related-facility="${c.facility}">Segnala non conformità</button><button class="btn" data-action="print">Stampa / PDF</button></div></div>`);}if(b.dataset.product){const p=products.find(p=>p.id===b.dataset.product);drawer('Scheda prodotto e comprova CAM',p.id,`<div class="drawer-body"><h2>${p.name}</h2>${details([['Produttore',p.maker],['Impianto',facilities[p.facility].name],['Funzione',p.use],['Quantità settembre',p.quantity+' '+p.unit],['Conformità',p.cam+' · dato demo'],['Evidenza attesa',p.label]])}<div class="ops-detail-note">SDS e scheda tecnica originali da collegare. I dati di conformità mostrati sono esempi, non attestazioni di prodotto.</div><button class="btn" data-action="print">Stampa scheda / PDF</button></div>`);}if(b.dataset.equipment){const m=equipment.find(m=>m.id===b.dataset.equipment);drawer('Scheda dotazione',m.id,`<div class="drawer-body"><h2>${m.name}</h2>${details([['Impianto',facilities[m.facility].name],['Tipo',m.type],['Utilizzo',m.use],['Ore macchina',m.hours===null?'Non applicabile':m.hours+' h'],['Stato',m.status],['Ultima manutenzione',m.last],['Prossima manutenzione',m.next],['Telemetria','Non collegata']])}<section class="detail-section"><h3>Registro manutenzioni</h3><p>${m.last} · Controllo funzionale · Esempio di registrazione.</p><p>${m.next} · Verifica programmata.</p></section><button class="btn" data-action="print">Stampa registro / PDF</button></div>`);}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){ops.page=1;ops.query='';ops.role=ops.level=ops.presence=ops.training=ops.complianceStatus='all';if(b.dataset.view==='sustainability'){ops.tab.sustainability='cam';ops.equipmentId=null;}document.body.classList.remove('home-menu-open');}if(b.dataset.action==='export'&&window.EXTRA_VIEWS[state.view]){e.stopImmediatePropagation();opExport('csv');}if(b.dataset.resolve){const n=ncs.find(n=>n.id===b.dataset.resolve);audits.push({id:n.id,facility:n.facility,origin:'DEC',at:new Date().toLocaleString('it-IT'),author:'DEC · sessione demo',old:n.status,next:'Risolta',event:'Registrazione ripristino'});}},true);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.susTab){ops.tab.sustainability=b.dataset.susTab;ops.equipmentId=null;ops.query='';ops.page=1;render();window.scrollTo({top:0,behavior:'smooth'});}if(b.dataset.equipmentOpen){ops.equipmentId=b.dataset.equipmentOpen;ops.tab.sustainability='machine-detail';render();window.scrollTo({top:0,behavior:'smooth'});}if(b.hasAttribute('data-equipment-back')){ops.tab.sustainability='machines';render();window.scrollTo({top:0,behavior:'smooth'});}if(b.dataset.camCategory!==undefined){ops.susCategory=b.dataset.camCategory||'all';render();}if(b.hasAttribute('data-sus-guide'))toast('Guida CAM disponibile nella sezione documentale della demo.');if(b.dataset.susEvidence)toast(`${b.dataset.susEvidence} evidenze documentali disponibili nella demo.`);},true);
document.addEventListener('change',e=>{if(e.target.id==='facility-select')ops.page=1;if(e.target.dataset.opsFilter){ops.page=1;ops[e.target.dataset.opsFilter]=e.target.value;render();}if(e.target.id==='cam-period'){ops.period=e.target.value;render();}});
document.addEventListener('change',e=>{if(e.target.id==='sus-type-select'){ops.susType=e.target.value;render();}if(e.target.id==='sus-status-select'){ops.susStatus=e.target.value;render();}},true);
document.addEventListener('input',e=>{if(e.target.id==='ops-query'){const p=e.target.selectionStart;ops.query=e.target.value;ops.page=1;render();const input=document.getElementById('ops-query');input.focus();input.setSelectionRange(p,p);}});
document.addEventListener('change',e=>{if(e.target.id==='facility-select')ops.page=1;},true);
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(titles[v])navigate(v);});
state.view=titles[location.hash.slice(1)]?location.hash.slice(1):'home';render();
